/**
 * IVX Production soak test — Phase 4
 * Duration: 2 hours (7200 s).
 * Safe request cadence:
 *   - /health, /version, /health/ready, /health/queue every 15 s
 *   - POST /api/public/chat every 5 min
 *   - POST /api/ivx/owner-passwordless-login + /api/ivx/owner-ai every 15 min
 *   - POST /api/ivx/owner-ai without auth (security gate) every 15 min
 * Logs to .rork/soak/soak-test-results.jsonl
 */

import { appendFileSync } from 'node:fs';

const BASE = 'https://ivx-holdings-platform.onrender.com';
const LOG_FILE = new URL('soak-test-results.jsonl', import.meta.url).pathname;
const DURATION_MS = 2 * 60 * 60 * 1000; // 2 hours

const OWNER_EMAIL = 'iperez4242@gmail.com';

function nowIso() {
  return new Date().toISOString();
}

function log(entry) {
  const line = JSON.stringify({ ts: nowIso(), ...entry }) + '\n';
  try {
    appendFileSync(LOG_FILE, line);
  } catch (e) {
    console.error('LOG WRITE FAILED:', e instanceof Error ? e.message : String(e));
  }
}

async function timedFetch(url, opts = {}) {
  const start = performance.now();
  try {
    const res = await fetch(url, { ...opts, signal: AbortSignal.timeout(opts.timeout ?? 15000) });
    const text = await res.text().catch(() => '');
    return { status: res.status, text, ms: Math.round(performance.now() - start) };
  } catch (e) {
    return { status: null, error: e instanceof Error ? e.message : String(e), ms: Math.round(performance.now() - start) };
  }
}

async function jsonFetch(url, opts = {}) {
  const r = await timedFetch(url, opts);
  if (r.status === null) return { ...r, body: null };
  try {
    return { ...r, body: JSON.parse(r.text) };
  } catch {
    return { ...r, body: null };
  }
}

function extractSha(body) {
  if (!body) return null;
  return body.commit ?? body.commitSha ?? body.sha ?? body.gitSha ?? body.git_commit ?? null;
}

async function healthBundle() {
  const paths = ['/health', '/version', '/health/ready', '/health/queue'];
  const results = await Promise.all(
    paths.map(async (p) => {
      const r = await jsonFetch(`${BASE}${p}`);
      return { path: p, status: r.status, ms: r.ms, sha: extractSha(r.body), error: r.error ?? null };
    }),
  );
  log({ event: 'health-bundle', results });
  return results;
}

async function publicChat() {
  const r = await jsonFetch(`${BASE}/api/public/chat`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'What is 2 plus 3?' }),
    timeout: 30000,
  });
  const ok = r.status === 200 && r.body && (r.body.ok || r.body.answer || r.body.text);
  log({ event: 'public-chat', status: r.status, ms: r.ms, ok, answerLength: String(r.body?.answer || r.body?.text || '').length, error: r.error ?? null });
  return ok;
}

async function ownerLoginAndAI() {
  const login = await jsonFetch(`${BASE}/api/ivx/owner-passwordless-login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: OWNER_EMAIL, emergency: 'ivx_emergency_recovery' }),
    timeout: 30000,
  });
  const token = login.body?.accessToken ?? '';
  const loginOk = login.status === 200 && token.length > 100;
  log({ event: 'owner-login', status: login.status, ms: login.ms, tokenLength: token.length, ok: loginOk, error: login.error ?? null });

  let aiOk = null;
  let aiStatus = null;
  if (loginOk) {
    const ai = await jsonFetch(`${BASE}/api/ivx/owner-ai`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({ message: 'How many properties do we have?' }),
      timeout: 60000,
    });
    aiOk = ai.status === 200 && (ai.body?.answer || ai.body?.text || ai.body?.provider);
    aiStatus = ai.status;
    log({ event: 'owner-ai', status: ai.status, ms: ai.ms, ok: aiOk, provider: ai.body?.provider ?? null, answerLength: String(ai.body?.answer || ai.body?.text || '').length, error: ai.error ?? null });
  }

  const sec = await jsonFetch(`${BASE}/api/ivx/owner-ai`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'test' }),
    timeout: 15000,
  });
  const secOk = sec.status === 401 || sec.status === 403;
  log({ event: 'security-gate', status: sec.status, ms: sec.ms, ok: secOk, error: sec.error ?? null });

  return { loginOk, aiOk, aiStatus, secOk };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function main() {
  const start = Date.now();
  log({ event: 'soak-start', base: BASE, durationMs: DURATION_MS, endAt: new Date(start + DURATION_MS).toISOString() });

  let iter = 0;
  let lastChat = 0;
  let lastOwner = 0;
  while (Date.now() - start < DURATION_MS) {
    iter++;
    const loopStart = Date.now();

    const health = await healthBundle();

    if (Date.now() - lastChat >= 5 * 60 * 1000) {
      await publicChat();
      lastChat = Date.now();
    }

    if (Date.now() - lastOwner >= 15 * 60 * 1000) {
      await ownerLoginAndAI();
      lastOwner = Date.now();
    }

    const health200 = health.every((h) => h.status === 200);
    const sha = health[0]?.sha ?? '?';
    console.log(`${nowIso()} iter=${iter} health=${health200 ? 'OK' : 'DEGRADED'} sha=${sha}`);

    const elapsed = Date.now() - loopStart;
    if (elapsed < 15_000) await sleep(15_000 - elapsed);
  }

  log({ event: 'soak-end', iterations: iter, durationMs: Date.now() - start });
  console.log(`${nowIso()} soak-end iterations=${iter}`);
}

main().catch((e) => {
  log({ event: 'soak-error', error: e instanceof Error ? e.message : String(e) });
  console.error('Soak test error:', e);
  process.exit(1);
});

